Shared ABI between kernel and userspace. Key contents:
```c
#define WEAKNET_KMOD_ABI_VERSION 2u
#define WEAKNET_KMOD_MAX_CPUS    256u
#define WEAKNET_KMOD_NR_SOFTIRQ  10u

struct wn_kmod_hdr {
	WN_U64 seq;
	WN_U64 sample_ns;   /* CLOCK_MONOTONIC 纳秒 */
	WN_U32 abi_version;
	WN_U32 nr_cpus;
};

struct wn_cpu_stat {
	WN_U32 cpu_id; WN_U32 online; WN_U32 valid; WN_U32 _pad;
	WN_U64 user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
};
struct wn_cpu_snapshot { struct wn_kmod_hdr hdr; struct wn_cpu_stat cpu[WEAKNET_KMOD_MAX_CPUS]; };

/* cnt[] 索引：0 HI, 1 TIMER, 2 NET_TX, 3 NET_RX, 4 BLOCK,
   5 IRQ_POLL, 6 TASKLET, 7 SCHED, 8 HRTIMER, 9 RCU */
struct wn_softirq_stat {
	WN_U32 cpu_id; WN_U32 online;
	WN_U64 cnt[WEAKNET_KMOD_NR_SOFTIRQ];
};
struct wn_softirq_snapshot { struct wn_kmod_hdr hdr; struct wn_softirq_stat cpu[WEAKNET_KMOD_MAX_CPUS]; };
```
Contains a long warning blockquote about mmap size: kernel uses `PAGE_ALIGN(sizeof(snapshot))`, userspace uses `sizeof(snapshot)`; a real past bug used cpu_stat's format to compute softirq's size (24600 instead of 22552, exceeding g_map_size 24576 → mmap EINVAL).

