### `server/src/host_pressure_monitor.cpp` — READ IN FULL (306 lines)
Key implementation details to mirror for softirq:
```cpp
#include "../../kmod/weaknet_kmod_abi.h"

constexpr int kMaxSeqRetry = 1000;

uint32_t loadSeq(const uint64_t* seq) {
    const volatile uint32_t* p = reinterpret_cast<const volatile uint32_t*>(seq);
    return __atomic_load_n(p, __ATOMIC_ACQUIRE);
}

// sample():
// 1. lazy open + mmap (retry each round, supports late module insert)
impl_->map_size = sizeof(struct wn_cpu_snapshot);
impl_->map = mmap(nullptr, impl_->map_size, PROT_READ, MAP_SHARED, impl_->fd, 0);
// 2. seqlock reader: s0 even → memcpy → fence → s1, accept if s0==s1
// 3. ABI check: local.hdr.abi_version != WEAKNET_KMOD_ABI_VERSION → "abi_mismatch"
// 4. build cur[] with busy/total
t.busy = c.user + c.nice + c.system + c.irq + c.softirq + c.steal;
t.total = t.busy + c.idle + c.iowait;
// 5. delta with skip conditions (offline now, offline prev, valid==0, backwards)
out.busy_ratio = static_cast<double>(sum_busy) / static_cast<double>(sum_total);
// clamped to [0,1]

// start_host_pressure_monitor_thread: dual publish
ctx->metrics_registry->publishScope(MetricScope::HOST, MetricId::CPU_BUSY_RATIO, sample);
weaknet::MetricsRegistry::global().publishScope(MetricScope::HOST, MetricId::CPU_BUSY_RATIO, sample);
// unavailable → MetricSample::unavailable() (never 0)
// 100ms slice sleep loop for responsive stop
```

