/**
 * @file observer_attribution.cpp
 * @brief 观测者降级归因实现
 */

#include "assurance/observer_attribution.hpp"

namespace weaknet {

namespace {

/// 已知的 observer 降级原因前缀。
///
/// 这些字符串由 src/dns_service_evaluator.hpp 的 checkObserverQuality() 产生，
/// 有单元测试逐条覆盖，是稳定契约。任何一项都表示「证据在传输/跟踪环节丢了」，
/// 而不是「网络本身观测到了故障」。
///
/// 注意 observer_unreliable_capture_emit_failure 与 observer_unreliable_event_loss
/// 是两级不同的丢失点（BPF 输出 vs perf 投递），刻意分开不合并——两者是否
/// 描述同一轮拥塞尚未验证，合并会掩盖真实边界。
constexpr const char* kObserverReasonPrefixes[] = {
    "observer_unreliable_capture_emit_failure",
    "observer_unreliable_event_loss",
    "observer_unreliable_ambiguity",
    "tracker_capacity_overflow",
};

bool isObserverDegradationReason(const std::string& reason) {
    for (const char* prefix : kObserverReasonPrefixes) {
        if (reason == prefix) return true;
    }
    return false;
}

}  // namespace

ObserverAttributionResult attributeObserverDegradation(
    const SleResult& sle,
    const std::string& sle_name,
    double cpu_busy,
    bool cpu_available,
    double cpu_threshold,
    double softirq_net_rx_share,
    bool softirq_available,
    double softirq_share_threshold) {
    ObserverAttributionResult res;
    res.trigger_sle = sle_name;
    res.observer_reason = sle.reason;
    res.cpu_threshold = cpu_threshold;
    res.softirq_share_threshold = softirq_share_threshold;

    // 1. 这个 SLE 根本没在报 observer 问题 → 不归因
    //
    // 注意不能只看 state：observer 降级时 SLE 可能是 UNKNOWN（无直接坏证据）
    // 也可能是 DEGRADED/BAD（有直接坏证据但观测不可靠）。判定依据必须是 reason。
    if (!isObserverDegradationReason(sle.reason)) {
        return res;
    }

    res.evaluated = true;
    res.cpu_available = cpu_available;
    res.observed_cpu_busy = cpu_busy;
    res.softirq_available = softirq_available;
    res.softirq_net_rx_share = softirq_net_rx_share;

    // 2. 没有 CPU 数据 → 老实说不知道
    //
    // 这是最常见的现场情况：内核模块不在 OTA manifest 里，设备上没有
    // /dev/weaknet_cpu_stat。此时绝不能因为"没数据"就默认 CPU 正常，
    // 也不能默认它有问题。UNATTRIBUTED 是唯一诚实的答案。
    if (!cpu_available) {
        res.attribution = ObserverAttribution::UNATTRIBUTED;
        res.explanation =
            "Observer quality degraded, but host CPU pressure data is unavailable; "
            "cause cannot be attributed (kernel module /dev/weaknet_cpu_stat not present)";
        res.evidence.push_back({"observer_attribution",
                                static_cast<double>(ObserverAttribution::UNATTRIBUTED),
                                "Observer degraded but host CPU data unavailable; not guessing"});
        return res;
    }

    // 3. CPU 高负载 → 高度怀疑是采集端自身过载
    if (cpu_busy >= cpu_threshold) {
        res.attribution = ObserverAttribution::SELF_INFLICTED;
        res.explanation =
            "Observer quality degraded while host CPU was saturated; "
            "evidence loss is most likely caused by the collector itself being starved of CPU, "
            "not by the observed network";
        res.evidence.push_back({"observer_attribution",
                                static_cast<double>(ObserverAttribution::SELF_INFLICTED),
                                "Observer degraded with high host CPU; suspect self-inflicted evidence loss"});
        res.evidence.push_back({"host_cpu_busy_ratio", cpu_busy,
                                "Host CPU busy ratio at the time of observer degradation"});

        // 3a. 细分：CPU 是被网络收包吃掉的，还是被别的负载吃掉的
        //
        // 这一步**不改 attribution**（仍是 SELF_INFLICTED），只补充一句
        // 说明与一条证据。处置方向完全不同：
        //   收包主导 → 采集端在处理被观测链路的流量，过载与观测对象相关
        //   其它主导 → 与网络无关的本机负载，属真正意义上的"自伤"
        //
        // 软中断数据不可用时保持沉默，**不加任何猜测性的解释**——
        // 与 UNATTRIBUTED 分支同一纪律：没数据就说没数据。
        if (softirq_available) {
            const bool rx_dominant = softirq_net_rx_share >= softirq_share_threshold;
            if (rx_dominant) {
                res.explanation +=
                    "; softirq activity is dominated by the network receive path, so the collector "
                    "was busy processing traffic from the observed link itself rather than an "
                    "unrelated local workload";
                res.evidence.push_back({"softirq_net_rx_share", softirq_net_rx_share,
                                        "Network receive softirqs dominate all softirq activity; "
                                        "CPU pressure correlates with observed traffic"});
            } else {
                res.explanation +=
                    "; softirq activity is NOT dominated by the network receive path, so the "
                    "collector was kept busy by an unrelated local workload instead of the "
                    "observed link's traffic";
                res.evidence.push_back({"softirq_net_rx_share", softirq_net_rx_share,
                                        "Network receive softirqs do not dominate softirq activity; "
                                        "CPU pressure comes from non-network local workloads"});
            }
        }
        return res;
    }

    // 4. CPU 正常 → 排除了过载这一个成因
    res.attribution = ObserverAttribution::NOT_HOST_CPU_BOUND;
    res.explanation =
        "Observer quality degraded while host CPU was within normal range; "
        "host CPU starvation is ruled out as the cause";
    res.evidence.push_back({"observer_attribution",
                            static_cast<double>(ObserverAttribution::NOT_HOST_CPU_BOUND),
                            "Observer degraded with normal host CPU; CPU starvation ruled out"});
    res.evidence.push_back({"host_cpu_busy_ratio", cpu_busy,
                            "Host CPU busy ratio at the time of observer degradation"});
    return res;
}

}  // namespace weaknet

/**
 * @file observer_attribution.hpp
 * @brief 观测者降级归因：区分「网络真的坏了」与「采集端自己过载」
 *
 * ============================================================================
 * 要解决的漏洞
 * ============================================================================
 *
 * 现有 Observer 质量判定（dns_service_evaluator.hpp 的 checkObserverQuality）
 * 只看 eBPF 的传输层失败率：capture_emit_failure_ratio / perf_delivery_loss_ratio /
 * ambiguity_ratio / insert_failure_ratio。任一项超阈值就判 observer unreliable。
 *
 * 但 observer unreliable 这件事本身有**两个完全不同的成因**：
 *
 *   (a) 环境/网络侧：内核拥塞、perf buffer 来不及消费、跟踪表被打满
 *       → 此时网络很可能真的有问题，UNKNOWN 是老实交代
 *
 *   (b) 采集端自身过载：板子 CPU 被打满（比如别的进程吃满 CPU），
 *       采集线程抢不到 CPU，于是本该产出的事件没能产出
 *       → 此时网络可能是好的，UNKNOWN 掩盖了一个**本机性能问题**
 *
 * 旧证据对 (a) 和 (b) 完全同形。后果是双向的：
 *   - 把 (b) 报成网络故障 → 现场人员去查网络，查不出问题
 *   - 把 (b) 报成"观测不可靠" → 真实原因（板子过载）永远不被暴露
 *
 * 本模块把 CPU 压力作为**第二个独立维度**叠上去，让这两种情况可以被区分。
 *
 * ============================================================================
 * 为什么单独一个模块，而不是改 DnsServiceEvaluator
 * ============================================================================
 *
 * DnsServiceEvaluator 的设计契约（见其类注释）是"无状态纯函数，只吃 DNS 事实"。
 * 把 CPU 压力塞进去会让**观测者的状态污染被观测对象的判定**：
 * 同一个 DNS 窗口，在板子忙时和空闲时会得出不同结论。那会让 SR 系列
 * 约束（同源纪律、证据可复现）全部失效，也让单元测试失去可判定性。
 *
 * 正确分层：
 *   第 1 层 DnsServiceEvaluator —— 只回答"DNS 自身观测到了什么"
 *   第 2 层 ObserverAttribution（本模块）—— 回答"那份观测为什么不可靠"
 *
 * 本模块**不修改**第 1 层的任何 state/coverage/reason，只在它旁边追加
 * 一个独立的归因结论。上层可以同时看到两句话，而不是看到一句被篡改的话。
 *
 * ============================================================================
 * 语义边界（不得越过）
 * ============================================================================
 *
 * - CPU 忙 **不能**推出"网络是好的"。它只能推出"观测者自己有问题"。
 * - CPU 闲 **不能**推出"网络坏了"。它只能排除"CPU 过载"这一个成因。
 * - 归因结论永远不参与 OverallPolicy 的评分与 veto，只作为证据与告警呈现。
 *   理由：过载是本机的运行状态，不是被评估链路的健康度。
 */

#pragma once

#include "assurance/health_state.hpp"
#include <string>
#include <vector>

namespace weaknet {

/**
 * @brief observer 降级成因的归因结果
 */
enum class ObserverAttribution {
    /// 观测质量没问题，无需归因
    NONE,

    /// 观测降级了，但没有 CPU 压力数据可用（模块未加载/首轮基线）
    /// → 老实说"不知道原因"，不得猜。
    UNATTRIBUTED,

    /// 观测降级 **且** 采集端 CPU 处于高负载
    /// → 高度怀疑是采集端自身过载导致丢证据，而不是网络故障
    SELF_INFLICTED,

    /// 观测降级 **且** 采集端 CPU 正常
    /// → 排除了"CPU 过载"这一个成因，故障更可能在被观测链路侧
    NOT_HOST_CPU_BOUND
};

inline const char* observerAttributionToString(ObserverAttribution a) {
    switch (a) {
        case ObserverAttribution::NONE: return "NONE";
        case ObserverAttribution::UNATTRIBUTED: return "UNATTRIBUTED";
        case ObserverAttribution::SELF_INFLICTED: return "SELF_INFLICTED";
        case ObserverAttribution::NOT_HOST_CPU_BOUND: return "NOT_HOST_CPU_BOUND";
        default: return "UNATTRIBUTED";
    }
}

/**
 * @brief 归因结果详情
 */
struct ObserverAttributionResult {
    ObserverAttribution attribution{ObserverAttribution::NONE};

    /// 是否真的做了一次归因（false 表示输入里没有 observer 降级迹象，直接返回）
    bool evaluated{false};

    /// 触发归因的 SLE 名（如 "dns_service"），便于多 SLE 场景下定位
    std::string trigger_sle;

    /// 被归因的原始降级原因（原样保留，绝不改写）
    std::string observer_reason;

    /// 归因阈值：CPU 忙碌比达到多少算"过载"
    double cpu_threshold{0.85};

    /// 实际观测到的 CPU 忙率（仅在 available 时有意义）
    double observed_cpu_busy{0.0};
    bool cpu_available{false};

    /**
     * @brief 软中断构成的细分（仅 SELF_INFLICTED 分支有意义）
     *
     * CPU 忙只回答"采集端过载了"，回答不了"过载是网络收包造成的，
     * 还是与网络无关的本机负载造成的"。这两者的处置方向完全相反：
     *   NET_RX 主导 → 采集端在拼命处理**被观测链路**的流量，
     *                 过载与观测对象强相关（流量是真的大）
     *   其它主导   → 与网络无关的本机负载，才是真正意义的"自伤"
     *
     * 这一层细分**不改变** ObserverAttribution 枚举值（仍然是
     * SELF_INFLICTED），只在 explanation 与 evidence 上补充说明。
     * 理由：加枚举值要同步序列化契约、云端 schema、全部真值表测试，
     * 而结论本身并没有多出一个新分类——只是把同一结论讲得更清楚。
     */
    double softirq_net_rx_share{0.0};
    bool softirq_available{false};

    /// 收包软中断占主导的判定阈值（默认 0.5）
    ///
    /// 注意：这是**事件计数**的构成比，不是时间占比。空载实测约 0.3%，
    /// 线速小包洪水可达 99%，中间几乎没有分布。0.5 落在这段空白里，
    /// 对"是不是收包把它压满的"这个问题足够可靠。
    double softirq_share_threshold{0.5};

    /// 人类可读解释（进 warnings / 证据 detail）
    std::string explanation;

    /// 机器可读证据条目，直接挂到 SleResult.evidence 上
    std::vector<EvidenceItem> evidence;
};

/**
 * @brief 归因判定（无状态纯函数）
 *
 * @param sle                     第 1 层评估结果（只读，不改）
 * @param sle_name                SLE 名称，进结果便于定位
 * @param cpu_busy                观测到的 CPU 忙率 0~1
 * @param cpu_available           CPU 数据是否可用（false 时 cpu_busy 被忽略）
 * @param cpu_threshold           CPU 忙率达到多少算"过载"
 * @param softirq_net_rx_share    收包软中断在全部软中断中的构成比 0~1
 * @param softirq_available       软中断数据是否可用（false 时上一参数被忽略）
 * @param softirq_share_threshold 构成比达到多少算"收包占主导"
 *
 * 判定规则：
 *   1. 若 sle.reason 不是已知的 observer 降级原因 → NONE，evaluated=false
 *   2. 若 CPU 数据不可用 → UNATTRIBUTED（不猜）
 *   3. CPU 忙率 >= 阈值 → SELF_INFLICTED
 *      3a. 软中断数据可用时，在 explanation 与 evidence 上细分为
 *          「收包路径主导」还是「非网络负载主导」
 *   4. 否则 → NOT_HOST_CPU_BOUND
 *
 * 第 3a 步只加证据与解释，**不改枚举值**：分类结论仍是 SELF_INFLICTED，
 * 只是把它讲清楚。加新枚举值会改序列化契约与云端 schema，而结论本身
 * 并没有多出一个新分类。
 *
 * 软中断参数带默认值，是为了让既有调用点与真值表测试完全不受影响：
 * 不传这些参数的调用，行为与引入本细分之前逐字一致。
 *
 * 为什么用 reason 字符串前缀而不是给 SleResult 加枚举字段：
 * 加字段会改动所有 SleResult 生产者的初始化路径与全部下游序列化，
 * 收益却只是省一次字符串比较。reason 已经是稳定契约（有单元测试覆盖），
 * 而这里一旦匹配不上只会退化成 NONE（保守：不归因），不会误报。
 */
ObserverAttributionResult attributeObserverDegradation(
    const SleResult& sle,
    const std::string& sle_name,
    double cpu_busy,
    bool cpu_available,
    double cpu_threshold = 0.85,
    double softirq_net_rx_share = 0.0,
    bool softirq_available = false,
    double softirq_share_threshold = 0.5);

}  // namespace weaknet

/**
 * @file host_pressure_monitor.cpp
 * @brief 采集端自身 CPU 压力 / 软中断构成的监控器实现
 *
 * 数据路径（两条并行，互不依赖）：
 *   kmod/weaknet_cpu_stat.c（内核 hrtimer，1 s）
 *     → /dev/weaknet_cpu_stat（只读 mmap，seqlock 保护）
 *     → HostCpuPressureSampler::sample()（区间差值 → 加权比率）
 *     → MetricsRegistry::publishScope(MetricScope::HOST, CPU_BUSY_RATIO)
 *     → quality 线程 / 诊断归因读取
 *
 *   kmod/weaknet_softirq.c（内核 hrtimer，1 s）
 *     → /dev/weaknet_softirq（只读 mmap，seqlock 保护）
 *     → HostSoftirqShareSampler::sample()（区间差值 → NET_RX 构成比）
 *     → MetricsRegistry::publishScope(MetricScope::HOST, SOFTIRQ_NET_RX_SHARE)
 *     → quality 线程 / 诊断归因读取
 *
 * 为什么这里直接 include kmod/weaknet_kmod_abi.h：
 *   那个头文件的存在意义就是"内核模块与用户态共享同一份结构定义"
 *   （见其文件头声明）。如果在服务端另抄一份，一旦内核侧改动结构体，
 *   服务端会在毫无征兆的情况下读到错位数据——而这个驱动 30 分钟长稳测试
 *   专门验过 seqlock 不撕裂，恰恰说明"读到的是稳定但错误的字段"这种
 *   故障最难发现。共享定义让编译器直接报错。
 *
 * 【必须记住的尺寸陷阱】：两个快照结构体大小不同，各自必须用**自己的**
 * 类型算 map 长度。历史上真实踩过：用 wn_cpu_snapshot 的 sizeof 去映射
 * softirq，得到 24600 > g_map_size 24576，内核直接返 EINVAL。
 * weaknet_kmod_abi.h 里有专门一段注释记录此事。
 */

#include "host_pressure_monitor.hpp"

#include "server.hpp"
#include "logger.hpp"
#include "metrics/metrics_registry.hpp"
#include "metrics/metric_types.hpp"
#include "metrics/metric_sample.hpp"

#include <cerrno>
#include <cstring>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

// 内核与用户态共享的 ABI 定义（纯数据结构，不含内核专有头）
#include "../../kmod/weaknet_kmod_abi.h"

namespace weaknet_dbus {

namespace {

/// seqlock 重试上限。正常写入窗口只覆盖一次 memcpy（8 核约 700 字节），
/// 用户态撞上奇数代次的概率极低；给足重试次数是为了在极端抢占下不误报失败。
constexpr int kMaxSeqRetry = 1000;

/**
 * @brief 以 32 位 acquire 语义读 seq 的低半字。
 *
 * 为什么不直接读 64 位：内核写 seq 用的是 WRITE_ONCE（在 arm64 上 64 位
 * 写本身原子），但用户态通过 mmap 读到的是同一块普通内存页，理论上存在
 * 缓存别名。32 位访问在两条架构上都保证不撕裂，代价可以忽略。
 */
uint32_t loadSeq(const uint64_t* seq) {
    const volatile uint32_t* p = reinterpret_cast<const volatile uint32_t*>(seq);
    return __atomic_load_n(p, __ATOMIC_ACQUIRE);
}

std::chrono::milliseconds readIntervalMs(const ServerContext* ctx) {
    const uint32_t ms = ctx->cfg.host_pressure.interval_ms.load();
    // 与配置层区间校验保持一致；越界值说明配置绕过了白名单，回落默认值而非崩溃
    if (ms < 1000 || ms > 600000) return std::chrono::milliseconds(15000);
    return std::chrono::milliseconds(ms);
}

}  // namespace

struct HostCpuPressureSampler::Impl {
    /// 单 CPU 的时间累计（纳秒），字段与 struct wn_cpu_stat 一一对应。
    struct CpuTimes {
        uint32_t cpu_id{0};
        bool online{false};
        bool valid{false};
        uint64_t busy{0};
        uint64_t total{0};
    };

    std::vector<CpuTimes> prev;
    bool have_prev{false};

    /// 映射在首次成功打开后保持，避免每轮 open/mmap 的开销
    int fd{-1};
    void* map{MAP_FAILED};
    size_t map_size{0};
};

HostCpuPressureSampler::HostCpuPressureSampler(std::string dev_path)
    : dev_path_(std::move(dev_path)), impl_(std::make_unique<Impl>()) {}

HostCpuPressureSampler::~HostCpuPressureSampler() {
    if (impl_ && impl_->map != MAP_FAILED) {
        munmap(impl_->map, impl_->map_size);
    }
    if (impl_ && impl_->fd >= 0) {
        close(impl_->fd);
    }
}

HostCpuPressure HostCpuPressureSampler::sample() {
    HostCpuPressure out;

    // ---- 1. 打开设备 + 映射（懒加载，失败后每轮重试，支持模块后插）----
    if (impl_->fd < 0) {
        impl_->fd = ::open(dev_path_.c_str(), O_RDONLY | O_CLOEXEC);
        if (impl_->fd < 0) {
            // 分类交给纯函数（可单测，见 host_pressure_monitor.hpp）。
            // errno 必须在任何其它调用之前捕获：std::strerror 之后 errno
            // 可能被改写。
            const int open_errno = errno;
            out.reason = openErrnoToReason(open_errno);
            out.detail = std::string("open: ") + std::strerror(open_errno);
            return out;
        }
        impl_->map_size = sizeof(struct wn_cpu_snapshot);
        impl_->map = mmap(nullptr, impl_->map_size, PROT_READ, MAP_SHARED, impl_->fd, 0);
        if (impl_->map == MAP_FAILED) {
            out.reason = "mmap_failed";
            out.detail = std::string("mmap: ") + std::strerror(errno);
            close(impl_->fd);
            impl_->fd = -1;
            return out;
        }
    }

    // ---- 2. seqlock 读者：校验 → 拷贝 → 再校验 ----
    auto* snap = static_cast<struct wn_cpu_snapshot*>(impl_->map);
    struct wn_cpu_snapshot local;

    uint32_t s0 = 0, s1 = 0;
    bool ok = false;
    for (int tries = 0; tries < kMaxSeqRetry; ++tries) {
        s0 = loadSeq(&snap->hdr.seq);
        if (s0 & 1u) continue;  // 内核正在写入

        std::memcpy(&local, snap, sizeof(local));

        // 拷贝完成后再校验一次：只在拷贝前校验会拿到半新半旧的数据
        __atomic_thread_fence(__ATOMIC_ACQUIRE);
        s1 = loadSeq(&snap->hdr.seq);

        if (s0 == s1) {
            ok = true;
            break;
        }
    }
    if (!ok) {
        out.reason = "read_failed";
        return out;
    }

    // ---- 3. ABI 版本校验：布局不符时宁可不可用，也不能拿错位数据当结论 ----
    if (local.hdr.abi_version != WEAKNET_KMOD_ABI_VERSION) {
        out.reason = "abi_mismatch";
        return out;
    }

    if (local.hdr.nr_cpus == 0) {
        out.reason = "no_delta_cpus";
        return out;
    }

    // ---- 4. 转成差值友好的形态 ----
    std::vector<Impl::CpuTimes> cur;
    cur.reserve(local.hdr.nr_cpus);
    for (uint32_t i = 0; i < local.hdr.nr_cpus && i < WEAKNET_KMOD_MAX_CPUS; ++i) {
        const auto& c = local.cpu[i];
        Impl::CpuTimes t;
        t.cpu_id = c.cpu_id;
        t.online = (c.online != 0);
        t.valid = (c.valid != 0);
        // 与内核 ABI 头同口径：guest 已含在 user 内，不重复计入 busy
        t.busy = c.user + c.nice + c.system + c.irq + c.softirq + c.steal;
        t.total = t.busy + c.idle + c.iowait;
        cur.push_back(t);
    }

    uint32_t online = 0;
    for (const auto& t : cur) {
        if (t.online) ++online;
    }
    out.online_cpus = online;

    if (!impl_->have_prev) {
        impl_->prev = std::move(cur);
        impl_->have_prev = true;
        out.reason = "baseline_only";
        return out;
    }

    // ---- 5. 区间差值 → 加权比率 ----
    //
    // 三个必须跳过的条件：
    //   a) 本轮离线
    //   b) 上一轮离线（离线期间累计冻结，上线后基准不对）
    //   c) valid=0（内核已判定这一对快照不可相减，如跨热插拔）
    //
    // 条件 c) 是内核侧显式给出的契约，不能自己用 "cur > prev" 之类的
    // 启发式去猜：一个恰好满足 cur > prev 的错误组合会算出荒唐值。
    uint64_t sum_busy = 0, sum_total = 0;
    uint32_t used = 0;

    for (const auto& c : cur) {
        const Impl::CpuTimes* p = nullptr;
        for (const auto& pc : impl_->prev) {
            if (pc.cpu_id == c.cpu_id) {
                p = &pc;
                break;
            }
        }
        if (!p || !c.online || !p->online || !c.valid || !p->valid) continue;
        if (c.total < p->total || c.busy < p->busy) continue;  // 防御性：累计值不应倒退

        sum_busy += (c.busy - p->busy);
        sum_total += (c.total - p->total);
        ++used;
    }

    impl_->prev = std::move(cur);

    if (used == 0 || sum_total == 0) {
        out.reason = "no_delta_cpus";
        return out;
    }

    out.available = true;
    out.sampled_cpus = used;
    out.busy_ratio = static_cast<double>(sum_busy) / static_cast<double>(sum_total);
    // 数值防御：差值序列理论上不会越界，但除以极小 sum_total 时仍可能得到 >1
    if (out.busy_ratio > 1.0) out.busy_ratio = 1.0;
    if (out.busy_ratio < 0.0) out.busy_ratio = 0.0;
    return out;
}

// ---------------------------------------------------------------------------
// 软中断构成比采样器
// ---------------------------------------------------------------------------

struct HostSoftirqShareSampler::Impl {
    /// 单 CPU 的十类软中断累计次数。
    ///
    /// 注意这里**没有** valid 字段：ABI 里 wn_softirq_stat 就没有（软中断
    /// 计数不会被热插拔清零）。防倒退改成用户态自查，见 sample() 第 5 步。
    struct CpuCounts {
        uint32_t cpu_id{0};
        bool online{false};
        uint64_t cnt[WEAKNET_KMOD_NR_SOFTIRQ]{};
    };

    std::vector<CpuCounts> prev;
    bool have_prev{false};

    int fd{-1};
    void* map{MAP_FAILED};
    size_t map_size{0};
};

HostSoftirqShareSampler::HostSoftirqShareSampler(std::string dev_path)
    : dev_path_(std::move(dev_path)), impl_(std::make_unique<Impl>()) {}

HostSoftirqShareSampler::~HostSoftirqShareSampler() {
    if (impl_ && impl_->map != MAP_FAILED) {
        munmap(impl_->map, impl_->map_size);
    }
    if (impl_ && impl_->fd >= 0) {
        close(impl_->fd);
    }
}

HostSoftirqShare HostSoftirqShareSampler::sample() {
    HostSoftirqShare out;

    // ---- 1. 打开设备 + 映射（懒加载，每轮重试，支持模块后插）----
    if (impl_->fd < 0) {
        impl_->fd = ::open(dev_path_.c_str(), O_RDONLY | O_CLOEXEC);
        if (impl_->fd < 0) {
            const int open_errno = errno;
            out.reason = openErrnoToReason(open_errno);
            out.detail = std::string("open: ") + std::strerror(open_errno);
            return out;
        }
        // 必须用 softirq 自己的类型算长度。用 wn_cpu_snapshot 会得到更大的
        // 值，超过内核 g_map_size 后 mmap 直接 EINVAL（历史真实 bug）。
        impl_->map_size = sizeof(struct wn_softirq_snapshot);
        impl_->map = mmap(nullptr, impl_->map_size, PROT_READ, MAP_SHARED, impl_->fd, 0);
        if (impl_->map == MAP_FAILED) {
            out.reason = "mmap_failed";
            out.detail = std::string("mmap: ") + std::strerror(errno);
            close(impl_->fd);
            impl_->fd = -1;
            return out;
        }
    }

    // ---- 2. seqlock 读者：校验 → 拷贝 → 再校验 ----
    auto* snap = static_cast<struct wn_softirq_snapshot*>(impl_->map);
    struct wn_softirq_snapshot local;

    uint32_t s0 = 0, s1 = 0;
    bool ok = false;
    for (int tries = 0; tries < kMaxSeqRetry; ++tries) {
        s0 = loadSeq(&snap->hdr.seq);
        if (s0 & 1u) continue;

        std::memcpy(&local, snap, sizeof(local));

        __atomic_thread_fence(__ATOMIC_ACQUIRE);
        s1 = loadSeq(&snap->hdr.seq);

        if (s0 == s1) {
            ok = true;
            break;
        }
    }
    if (!ok) {
        out.reason = "read_failed";
        return out;
    }

    // ---- 3. ABI 版本校验 ----
    if (local.hdr.abi_version != WEAKNET_KMOD_ABI_VERSION) {
        out.reason = "abi_mismatch";
        return out;
    }

    if (local.hdr.nr_cpus == 0) {
        out.reason = "no_delta_cpus";
        return out;
    }

    // ---- 4. 转成差值友好的形态 ----
    std::vector<Impl::CpuCounts> cur;
    cur.reserve(local.hdr.nr_cpus);
    for (uint32_t i = 0; i < local.hdr.nr_cpus && i < WEAKNET_KMOD_MAX_CPUS; ++i) {
        const auto& c = local.cpu[i];
        Impl::CpuCounts t;
        t.cpu_id = c.cpu_id;
        t.online = (c.online != 0);
        for (uint32_t k = 0; k < WEAKNET_KMOD_NR_SOFTIRQ; ++k) {
            t.cnt[k] = c.cnt[k];
        }
        cur.push_back(t);
    }

    uint32_t online = 0;
    for (const auto& t : cur) {
        if (t.online) ++online;
    }
    out.online_cpus = online;

    if (!impl_->have_prev) {
        impl_->prev = std::move(cur);
        impl_->have_prev = true;
        out.reason = "baseline_only";
        return out;
    }

    // ---- 5. 区间差值 → NET_RX 构成比 ----
    //
    // 与 CPU 采样器同款跳过条件（a 本轮离线 / b 上轮离线），再加一条
    // 本模块专有的防倒退检查（c）：
    //
    //   软中断计数是纯递增的，理论上不该倒退。但 ABI 没有 valid 标记可以
    //   依赖，而「理论上不该发生」正是最难发现的故障来源。任一类计数变小
    //   就跳过该 CPU——比起算出荒唐的负增量，少统计一个核的代价可以忽略。
    uint64_t net_rx = 0, total = 0;
    uint32_t used = 0;

    for (const auto& c : cur) {
        const Impl::CpuCounts* p = nullptr;
        for (const auto& pc : impl_->prev) {
            if (pc.cpu_id == c.cpu_id) {
                p = &pc;
                break;
            }
        }
        if (!p || !c.online || !p->online) continue;

        bool backwards = false;
        uint64_t cpu_total = 0;
        for (uint32_t k = 0; k < WEAKNET_KMOD_NR_SOFTIRQ; ++k) {
            if (c.cnt[k] < p->cnt[k]) {
                backwards = true;
                break;
            }
            cpu_total += (c.cnt[k] - p->cnt[k]);
        }
        if (backwards) continue;

        net_rx += (c.cnt[3] - p->cnt[3]);   // 索引 3 = NET_RX，见 ABI 头
        total += cpu_total;
        ++used;
    }

    impl_->prev = std::move(cur);

    out.sampled_cpus = used;
    out.net_rx_delta = net_rx;
    out.total_softirq_delta = total;

    if (used == 0) {
        out.reason = "no_delta_cpus";
        return out;
    }

    // 窗口内一次软中断都没触发（分母为 0）：构成比在数学上无定义。
    // 绝不回落成 0——0 会被读成「完全没有收包软中断」，是伪造的观测。
    if (total == 0) {
        out.reason = "no_softirq_activity";
        return out;
    }

    out.available = true;
    out.net_rx_share = static_cast<double>(net_rx) / static_cast<double>(total);
    if (out.net_rx_share > 1.0) out.net_rx_share = 1.0;
    if (out.net_rx_share < 0.0) out.net_rx_share = 0.0;
    return out;
}

namespace {

/// 双发一个 HOST 域指标到两处注册中心。
///
/// 抽成函数是为了让 CPU 与 softirq 两条发布路径**完全同构**——包括
/// 「不可用时发 UNAVAILABLE 绝不发 0」这条不能走样的纪律。
/// global() 那一份是 database_manager.cpp 唯一会读的，漏发会让指标
/// 永远进不了 SQLite。
void publishHostMetric(ServerContext* ctx, weaknet::MetricId id, bool available, double value) {
    if (!ctx->metrics_registry) return;
    const auto sample = available ? weaknet::MetricSample::valid(value)
                                  : weaknet::MetricSample::unavailable();
    ctx->metrics_registry->publishScope(weaknet::MetricScope::HOST, id, sample);
    weaknet::MetricsRegistry::global().publishScope(weaknet::MetricScope::HOST, id, sample);
}

}  // namespace

void start_host_pressure_monitor_thread(ServerContext* ctx, std::thread* worker) {
    // 可 join 句柄，由 MonitorManager 在停止时 join，避免 detached 线程在
    // ctx 析构后野访问（与 rtt_monitor 等既有监控器同一纪律）。
    *worker = std::thread([ctx] {
        LOG_INFO(LogModule::HOST_PRESSURE, "host pressure monitor thread started");

        HostCpuPressureSampler cpu_sampler;
        HostSoftirqShareSampler softirq_sampler;

        while (ctx->running.load() && !ctx->host_pressure_stop.load()) {
            try {
                const auto interval = readIntervalMs(ctx);

                // ---- 采样 1：CPU 忙碌比（时间维度）----
                //
                // 两个采样**顺序执行且互不短路**：即使 cpu_stat 不可用，
                // softirq 也照常采。两者是独立证据，任一个缺失都不该
                // 让另一个跟着哑掉。
                const HostCpuPressure p = cpu_sampler.sample();
                publishHostMetric(ctx, weaknet::MetricId::CPU_BUSY_RATIO,
                                 p.available, p.busy_ratio);

                if (p.available) {
                    LOG_INFO(LogModule::HOST_PRESSURE,
                             "cpu_busy_ratio=" << p.busy_ratio
                             << " (" << p.sampled_cpus << "/" << p.online_cpus
                             << " cpus sampled)");
                } else if (p.reason != "baseline_only") {
                    // 不可用时发布 UNAVAILABLE，**不发布 0**：
                    // 0 会被下游解读成"CPU 很闲"，从而掩盖真实故障。
                    // baseline_only 是启动后的正常状态，不值得刷警告。
                    //
                    // detail 必须打出来：reason 只说"打不开"，
                    // detail 才说"是 EPERM 还是 ENOENT"，而这两者
                    // 的处置完全不同（改 capability vs 装模块）。
                    LOG_WARNING(LogModule::HOST_PRESSURE,
                                "cpu pressure unavailable: " << p.reason
                                << (p.detail.empty() ? "" : " (" + p.detail + ")"));
                }

                // ---- 采样 2：软中断构成比（类型维度）----
                const HostSoftirqShare q = softirq_sampler.sample();
                publishHostMetric(ctx, weaknet::MetricId::SOFTIRQ_NET_RX_SHARE,
                                 q.available, q.net_rx_share);

                if (q.available) {
                    // 把分子分母一起打出来：只有构成比时，一个"38%"看不出
                    // 是几万次还是几亿次里算出来的，排障时没法判断量级。
                    LOG_INFO(LogModule::HOST_PRESSURE,
                             "softirq_net_rx_share=" << q.net_rx_share
                             << " (net_rx=" << q.net_rx_delta
                             << "/total=" << q.total_softirq_delta
                             << ", " << q.sampled_cpus << "/" << q.online_cpus
                             << " cpus sampled)");
                } else if (q.reason != "baseline_only") {
                    LOG_WARNING(LogModule::HOST_PRESSURE,
                                "softirq share unavailable: " << q.reason
                                << (q.detail.empty() ? "" : " (" + q.detail + ")"));
                }

                // 100 ms 分片等待：整段睡眠会让停止请求最长等一个完整周期
                const int slices = static_cast<int>(interval.count() / 100);
                for (int i = 0; i < slices && ctx->running.load() &&
                                !ctx->host_pressure_stop.load();
                     ++i) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(100));
                }
            } catch (const std::exception& e) {
                LOG_ERROR(LogModule::HOST_PRESSURE,
                          "host pressure monitor exception: " << e.what());
            } catch (...) {
                LOG_ERROR(LogModule::HOST_PRESSURE,
                          "host pressure monitor unknown exception");
            }
        }

        LOG_INFO(LogModule::HOST_PRESSURE, "host pressure monitor thread exiting");
    });
}

}  // namespace weaknet_dbus

/**
 * @file host_pressure_monitor.hpp
 * @brief 采集端自身 CPU 压力监控器
 *
 * 目的不是"多采一个指标"，而是补上证据链里的一个真实漏洞：
 *
 *   现有 Observer 质量判定（assurance/dns_service_evaluator.hpp 的
 *   checkObserverQuality）只看 eBPF 的 capture_emit_failure_ratio。
 *   但"BPF 掉证据"有两个完全不同的成因：
 *     (a) 网络/内核真的出了问题
 *     (b) 板子 CPU 被打满，采集线程抢不到 CPU，perf buffer 来不及消费
 *   旧证据无法区分这两者，于是 (b) 会被误判成网络故障。
 *
 * 本监控器把"观测者自身状态"变成可判定的证据，让归因能往下分辨一层。
 *
 * 数据来源：kmod/weaknet_cpu_stat，内核 hrtimer 每 4 ms 采集 per-CPU 累计时间
 * （user/nice/system/idle/iowait/irq/softirq/steal/guest/guest_nice），
 * 经 /dev/weaknet_cpu_stat 只读 mmap 暴露，seqlock 保证快照一致性。
 * 该模块已实测 30 分钟长稳：5851 万次读取零失败、进程 RSS 零增长。
 *
 * 重要语义边界（不要越过）：
 *   CPU 忙 只能说明"采集端可能来不及处理"，**不能**说明网络坏了，
 *   也**不能**说明网络没坏。它是归因辅助证据，不是故障判据本身。
 *
 * 可用性降级（关键）：
 *   内核模块不在 OTA manifest 里，现场设备大概率没有这个设备节点。
 *   此时必须发布 UNAVAILABLE 并让整条业务链路表现得与引入本插件之前
 *   完全一致 —— 绝不伪造 0，也绝不因为缺数据而改变任何已有判定。
 */

#pragma once

#include <cerrno>
#include <cstdint>
#include <memory>
#include <string>
#include <thread>
#include <vector>

namespace weaknet_dbus {

class ServerContext;

/**
 * @brief 把 open(2) 的 errno 映射成 HostCpuPressure 的机器可读原因
 *
 * 为什么单独抽成纯函数：分类逻辑必须能被单测钉死，而"造一个真实的
 * EPERM/EACCES 让 open 失败"在 root 与普通用户下行为不同（root 会绕过
 * 大部分权限检查），做不出稳定的测试夹具。把纯逻辑分离出来，
 * 测试就不依赖运行身份。
 *
 * 语义边界（这条边界是踩坑换来的）：
 *   ENOENT / ENXIO  → "device_absent"：设备节点根本没有，模块没加载。
 *                     这是现场设备的**常态**，属预期降级。
 *   EPERM / EACCES  → "open_failed"：设备在，但当前进程权限不够。
 *                     处置方式是改 capability，与装模块完全不同。
 *   其它             → "open_failed"：一律归入"打不开"，绝不冒充缺失。
 *
 * 历史教训（2026-11-07 真机）：模块的 open() 只校验 CAP_SYS_ADMIN，而服务
 * 的 systemd 单元只授予 CAP_PERFMON。设备节点明明存在，服务端却持续报
 * "device_absent" —— 因为这里曾经把所有 open 失败都归成这一个原因，
 * 直接掩盖了真因，误导排查方向。
 */
inline const char* openErrnoToReason(int err) {
    switch (err) {
        case ENOENT:
        case ENXIO:
            return "device_absent";
        default:
            return "open_failed";
    }
}

/**
 * @brief 一次 CPU 压力采样结果
 */
struct HostCpuPressure {
    /// 本轮是否得到了可用的比率。false 时 @busy_ratio 无意义。
    bool available{false};

    /// 全系统 CPU 忙碌占比 0~1。
    ///
    /// 多核**按累计时间加权**：sum(busy) / sum(total)，不是各核比率的算术平均。
    /// 这不是风格问题而是语义问题：8 核中 1 核 100%、其余空闲时两者都等于 0.125，
    /// 但当各核 total 不等（CPU 隔离、tickless 空闲核）时会分叉，
    /// 只有加权和才等于"系统整体花在 busy 上的时间比例"。
    double busy_ratio{0.0};

    /// 参与本轮差值的 CPU 数（已排除离线核与累计值被热插拔重置的核）
    uint32_t sampled_cpus{0};

    /// 系统在线 CPU 总数（含本轮未参与差值的核）
    uint32_t online_cpus{0};

    /// available=false 时的机器可读原因：
    ///   "device_absent"    设备节点不存在（模块未加载）
    ///   "open_failed"      打开失败（权限/被占用）
    ///   "mmap_failed"      映射失败（ABI 尺寸不匹配）
    ///   "abi_mismatch"     abi_version 不符
    ///   "baseline_only"    首轮采样，只建立基线，无差值可算
    ///   "read_failed"      seqlock 重试耗尽
    ///   "no_delta_cpus"    两次采样间没有任何核可做差值
    std::string reason;

    /// available=false 时的人类可读补充信息（errno 文本等）。
    ///
    /// 与 @reason 分工：@reason 是机器可读的分类，@detail 是排障线索。
    /// 只用于日志，**不得**作为判定依据——分类判断一律看 @reason。
    std::string detail;
};

/**
 * @brief CPU 压力采样器
 *
 * 有状态：保留上一份快照才能做区间差值。
 *
 * 为什么必须做差值而不是直接用累计值：
 *   /dev/weaknet_cpu_stat 发布的是**自开机以来的累计纳秒**。
 *   直接用累计值算比率得到的是"开机至今的平均负载"——一个持续十小时的
 *   开机过程里，本轮评估期间的瞬时尖峰会被完全抹平，用来判断
 *   "这一轮采集端是否过载"毫无意义。只有相邻两次采样的差值反映当前区间。
 *
 * 线程安全：非线程安全。同一实例只应由一个线程持有使用。
 */
class HostCpuPressureSampler {
public:
    explicit HostCpuPressureSampler(std::string dev_path = "/dev/weaknet_cpu_stat");
    ~HostCpuPressureSampler();

    HostCpuPressureSampler(const HostCpuPressureSampler&) = delete;
    HostCpuPressureSampler& operator=(const HostCpuPressureSampler&) = delete;

    /**
     * @brief 采一次样并与上一样本做差值
     *
     * 首次调用只建立基线，返回 available=false, reason="baseline_only"。
     * 这是刻意行为：没有前一份样本时任何比率都是凭空捏造。
     *
     * 设备不存在时返回 available=false, reason="device_absent"；
     * 调用方据此发布 UNAVAILABLE，不得回落成 0。
     */
    HostCpuPressure sample();

    const std::string& devPath() const { return dev_path_; }

private:
    struct Impl;

    std::string dev_path_;
    std::unique_ptr<Impl> impl_;
};

/**
 * @brief 一次软中断构成比采样结果
 *
 * 与 HostCpuPressure 的关系：两者互补，不可互相替代。
 *   HostCpuPressure  回答「忙不忙」（CPU 时间维度）
 *   本结构           回答「忙在哪」（软中断类型维度）
 */
struct HostSoftirqShare {
    /// 本轮是否得到了可用的构成比。false 时 @net_rx_share 无意义。
    bool available{false};

    /// 收包软中断（NET_RX）增量在**全部十类软中断**增量中的占比 0~1。
    ///
    /// 数值边界：这是**事件计数**的构成比，不是时间占比。
    ///   空载时 NET_RX 只有约 0.3%（TIMER/SCHED/RCU 在空闲时照常触发，
    ///   把分母撑得很大）；线速小包洪水可到 99%。
    ///   所以判断「高」要按数量级，不能按「过半数」。
    double net_rx_share{0.0};

    /// 本轮统计窗口内收包软中断的触发次数（增量），仅用于日志与排障。
    uint64_t net_rx_delta{0};

    /// 全部十类软中断的增量合计，即构成比的分母。
    uint64_t total_softirq_delta{0};

    /// 参与本轮差值的 CPU 数（已排除离线核与计数倒退核）
    uint32_t sampled_cpus{0};

    /// 系统在线 CPU 总数
    uint32_t online_cpus{0};

    /// available=false 时的机器可读原因（取值与 HostCpuPressure 同构）：
    ///   "device_absent" / "open_failed" / "mmap_failed" / "abi_mismatch"
    ///   "baseline_only" / "read_failed" / "no_delta_cpus"
    ///   额外一个本模块专有值：
    ///   "no_softirq_activity"  窗口内十类软中断一次都没触发（分母为 0），
    ///                          构成比无定义 —— 绝不回落成 0
    std::string reason;

    /// available=false 时的人类可读补充信息（errno 文本等）
    std::string detail;
};

/**
 * @brief 软中断构成比采样器
 *
 * 有状态：保留上一份快照才能做区间差值（原因与 HostCpuPressureSampler 相同）。
 *
 * 为什么必须按**类型构成比**发布，而不是直接发布 NET_RX 触发次数：
 *   触发次数与流量强度、包大小、NAPI 轮询行为全都相关，跨设备跨场景
 *   没有可比阈值。而「收包在所有软中断里占多大份额」回答的是
 *   「这块 CPU 的时间瓶颈是不是被网络收包占住了」，这个才与归因有关。
 *
 * 与 CPU 采样器的一个重要差异：ABI 里 wn_softirq_stat **没有 valid 字段**
 * （见 weaknet_kmod_abi.h），因为软中断计数是纯递增次数，不像 idle/iowait
 * 那样会被 tick_cancel_sched_timer() 清零。但这并不等于不需要防倒退——
 * 用户态仍然自查两道：online 翻转、任一类计数变小。真出现倒退说明
 * 前提被破坏（内核行为变化或 ABI 错配），此时跳过该 CPU 而不是硬算。
 *
 * 线程安全：非线程安全。同一实例只应由一个线程持有使用。
 */
class HostSoftirqShareSampler {
public:
    explicit HostSoftirqShareSampler(std::string dev_path = "/dev/weaknet_softirq");
    ~HostSoftirqShareSampler();

    HostSoftirqShareSampler(const HostSoftirqShareSampler&) = delete;
    HostSoftirqShareSampler& operator=(const HostSoftirqShareSampler&) = delete;

    /**
     * @brief 采一次样并与上一样本做差值
     *
     * 首次调用只建立基线，返回 available=false, reason="baseline_only"。
     * 设备不存在时返回 available=false, reason="device_absent"。
     */
    HostSoftirqShare sample();

    const std::string& devPath() const { return dev_path_; }

private:
    struct Impl;

    std::string dev_path_;
    std::unique_ptr<Impl> impl_;
};

/**
 * @brief 启动 CPU 压力监控线程
 *
 * 同一线程内**顺序采两个模块**：先 cpu_stat，再 softirq。
 *
 * 为什么放在同一个线程而不是各开一个：
 *   (a) 归因时需要两者属于同一轮评估，同一线程天然对齐采样节奏；
 *   (b) 停止标志、配置键（host_pressure.enabled / interval_ms）只有一份，
 *       不新增配置表面；
 *   (c) 两个设备都是 15 秒一次的低频采样，线程开销可以忽略。
 *
 * 两者**互不阻塞**：任一个不可用只影响自己发布 UNAVAILABLE，另一个照常工作。
 */
void start_host_pressure_monitor_thread(ServerContext* ctx, std::thread* worker);

}  // namespace weaknet_dbus

#pragma once

#include <string>
#include <chrono>
#include <cstdint>

namespace weaknet {

enum class MetricId {
    RTT_MS,
    REACHABILITY_SUCCESS,
    JITTER_MS,
    TCP_LOSS_RATE,
    WIFI_LOSS_RATE,
    RSSI_DBM,
    TRAFFIC_BPS,
    TRAFFIC_PPS,
    TRAFFIC_FLOWS,
    BAND_CONFLICT,
    DNS_QUERIES,
    DNS_FAILURE_RATIO,
    DNS_LATENCY_P50_MS,
    DNS_INFLIGHT,
    TCP_RETRANS_LOSS_PCT,
    TCP_CONN_ACTIVE,
    TCP_CONN_ACCEPT_RATE,

    /// 采集端自身 CPU 压力（HOST 域，0~1）。
    ///
    /// 存在的理由不是"多一个指标"，而是回答一个现有证据链答不出的问题：
    /// eBPF 掉证据（capture_emit_failure_ratio 高）到底是**网络真的坏了**，
    /// 还是**板子 CPU 被打满、采集线程抢不到 CPU**。二者在旧证据上完全同形，
    /// 会把采集端过载误判成网络故障。
    ///
    /// 本指标把"观测者自身状态"变成一等证据，使归因可以往下分辨一层。
    /// 数据来源是 kmod/weaknet_cpu_stat（4 ms 粒度的 per-CPU 累计时间）。
    CPU_BUSY_RATIO,

    /// 收包软中断在**全部软中断**中所占的构成比（HOST 域，0~1）。
    ///
    /// 存在的理由：CPU_BUSY_RATIO 只能回答"板子忙不忙"，回答不了"忙在哪"。
    /// 采集端被打满时，两种成因的处置方向完全相反：
    ///   (a) 收包软中断占主导 → CPU 是在处理被观测链路的流量，
    ///       证据丢失与**观测到的流量本身**相关，不是无关进程捣乱；
    ///   (b) 其它软中断/用户态占主导 → 与网络无关的本机负载，
    ///       属于真正意义上的"自伤"。
    ///
    /// 数值边界（务必记住，否则会把结论读反）：
    ///   本指标是**软中断事件数的构成比**，不是时间占比，也不是饱和率。
    ///   板端实测空载时 NET_RX 仅占约 0.3%（TIMER/SCHED/RCU 这些定频
    ///   软中断在空闲时照常触发，把分母撑得很大）；线速小包洪水可到 99%。
    ///   因此"高"是按数量级判的，不是"过半数"。
    ///
    /// 单独看没有意义：一台跑大流量的机器 NET_RX 占比天然就高。它唯一的
    /// 用法是作为 CPU_BUSY_RATIO 的**限定词**，只在"CPU 已饱和"这个分支里
    /// 被咨询。因此它不参与任何评分与 veto，只进归因证据。
    ///
    /// 数据来源是 kmod/weaknet_softirq（per-CPU 十类软中断累计触发次数）。
    SOFTIRQ_NET_RX_SHARE
};

inline const char* metricIdToString(MetricId id) {
    switch (id) {
        case MetricId::RTT_MS: return "rtt_ms";
        case MetricId::REACHABILITY_SUCCESS: return "reachability_success";
        case MetricId::JITTER_MS: return "jitter_ms";
        case MetricId::TCP_LOSS_RATE: return "tcp_loss_rate";
        case MetricId::WIFI_LOSS_RATE: return "wifi_loss_rate";
        case MetricId::RSSI_DBM: return "rssi_dbm";
        case MetricId::TRAFFIC_BPS: return "traffic_bps";
        case MetricId::TRAFFIC_PPS: return "traffic_pps";
        case MetricId::TRAFFIC_FLOWS: return "traffic_flows";
        case MetricId::BAND_CONFLICT: return "band_conflict";
        case MetricId::DNS_QUERIES: return "dns_queries";
        case MetricId::DNS_FAILURE_RATIO: return "dns_failure_ratio";
        case MetricId::DNS_LATENCY_P50_MS: return "dns_latency_p50_ms";
        case MetricId::DNS_INFLIGHT: return "dns_inflight";
        case MetricId::TCP_RETRANS_LOSS_PCT: return "tcp_retrans_loss_pct";
        case MetricId::TCP_CONN_ACTIVE: return "tcp_conn_active";
        case MetricId::TCP_CONN_ACCEPT_RATE: return "tcp_conn_accept_rate";
        case MetricId::CPU_BUSY_RATIO: return "cpu_busy_ratio";
        case MetricId::SOFTIRQ_NET_RX_SHARE: return "softirq_net_rx_share";
        default: return "unknown";
    }
}

enum class MetricState {
    VALID,
    STALE,
    UNAVAILABLE,
    NOT_APPLICABLE,
    ERROR
};

inline const char* metricStateToString(MetricState state) {
    switch (state) {
        case MetricState::VALID: return "VALID";
        case MetricState::STALE: return "STALE";
        case MetricState::UNAVAILABLE: return "UNAVAILABLE";
        case MetricState::NOT_APPLICABLE: return "NOT_APPLICABLE";
        case MetricState::ERROR: return "ERROR";
        default: return "UNKNOWN";
    }
}

enum class MetricUnit {
    MILLISECONDS,
    PERCENT,
    DBM,
    BYTES_PER_SEC,
    PACKETS_PER_SEC,
    COUNT,
    BOOLEAN
};

enum class MetricScope {
    INTERFACE,
    GLOBAL,
    HOST,
    RESOLVER
};

enum class SourceSemantics {
    GAUGE,
    EVENT,
    INTERVAL_DELTA_RATE,
    CUMULATIVE_COUNTER
};

enum class PublishedSemantics {
    GAUGE,
    EVENT,
    INTERVAL_RATE
};

struct MetricDescriptor {
    MetricId id;
    std::string name;
    MetricUnit unit;
    MetricScope scope;
    SourceSemantics source_semantics;
    PublishedSemantics published_semantics;
    std::chrono::milliseconds expected_interval;
    std::chrono::milliseconds freshness;
};

inline MetricDescriptor getMetricDescriptor(MetricId id) {
    using namespace std::chrono_literals;
    switch (id) {
        case MetricId::RTT_MS:
            return {MetricId::RTT_MS, "rtt_ms", MetricUnit::MILLISECONDS, MetricScope::INTERFACE,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::REACHABILITY_SUCCESS:
            return {MetricId::REACHABILITY_SUCCESS, "reachability_success", MetricUnit::BOOLEAN, MetricScope::INTERFACE,
                    SourceSemantics::EVENT, PublishedSemantics::EVENT, 10000ms, 30000ms};
        case MetricId::JITTER_MS:
            return {MetricId::JITTER_MS, "jitter_ms", MetricUnit::MILLISECONDS, MetricScope::INTERFACE,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::TCP_LOSS_RATE:
            return {MetricId::TCP_LOSS_RATE, "tcp_loss_rate", MetricUnit::PERCENT, MetricScope::INTERFACE,
                    SourceSemantics::INTERVAL_DELTA_RATE, PublishedSemantics::INTERVAL_RATE, 10000ms, 30000ms};
        case MetricId::WIFI_LOSS_RATE:
            return {MetricId::WIFI_LOSS_RATE, "wifi_loss_rate", MetricUnit::PERCENT, MetricScope::INTERFACE,
                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::INTERVAL_RATE, 10000ms, 30000ms};
        case MetricId::RSSI_DBM:
            return {MetricId::RSSI_DBM, "rssi_dbm", MetricUnit::DBM, MetricScope::INTERFACE,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::TRAFFIC_BPS:
            return {MetricId::TRAFFIC_BPS, "traffic_bps", MetricUnit::BYTES_PER_SEC, MetricScope::INTERFACE,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::TRAFFIC_PPS:
            return {MetricId::TRAFFIC_PPS, "traffic_pps", MetricUnit::PACKETS_PER_SEC, MetricScope::INTERFACE,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::TRAFFIC_FLOWS:
            return {MetricId::TRAFFIC_FLOWS, "traffic_flows", MetricUnit::COUNT, MetricScope::INTERFACE,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::BAND_CONFLICT:
            return {MetricId::BAND_CONFLICT, "band_conflict", MetricUnit::BOOLEAN, MetricScope::INTERFACE,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::DNS_QUERIES:
            return {MetricId::DNS_QUERIES, "dns_queries", MetricUnit::COUNT, MetricScope::GLOBAL,
                    SourceSemantics::EVENT, PublishedSemantics::EVENT, 10000ms, 30000ms};
        case MetricId::DNS_FAILURE_RATIO:
            return {MetricId::DNS_FAILURE_RATIO, "dns_failure_ratio", MetricUnit::PERCENT, MetricScope::GLOBAL,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::DNS_LATENCY_P50_MS:
            return {MetricId::DNS_LATENCY_P50_MS, "dns_latency_p50_ms", MetricUnit::MILLISECONDS, MetricScope::GLOBAL,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::DNS_INFLIGHT:
            return {MetricId::DNS_INFLIGHT, "dns_inflight", MetricUnit::COUNT, MetricScope::GLOBAL,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::TCP_RETRANS_LOSS_PCT:
            return {MetricId::TCP_RETRANS_LOSS_PCT, "tcp_retrans_loss_pct", MetricUnit::PERCENT, MetricScope::GLOBAL,
                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::INTERVAL_RATE, 10000ms, 30000ms};
        case MetricId::TCP_CONN_ACTIVE:
            return {MetricId::TCP_CONN_ACTIVE, "tcp_conn_active", MetricUnit::COUNT, MetricScope::GLOBAL,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
        case MetricId::TCP_CONN_ACCEPT_RATE:
            return {MetricId::TCP_CONN_ACCEPT_RATE, "tcp_conn_accept_rate", MetricUnit::COUNT, MetricScope::GLOBAL,
                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::INTERVAL_RATE, 10000ms, 30000ms};
        case MetricId::CPU_BUSY_RATIO:
            /*
             * HOST 域首个投入使用的指标（MetricScope::HOST 在此之前只有
             * metrics_registry.hpp 的 scopeKey() 拼接逻辑，从无指标使用）。
             *
             * 语义：全系统 CPU 忙碌占比 0~1（多核按累计时间加权，不是算术平均，
             * 避免单核打满被 8 核平均稀释掉）。
             *
             * GAUGE：源数据是 /dev/weaknet_cpu_stat 的**累计**纳秒，但本驱动的
             * 插件内部已经做了区间差值并只发布比率，因此对外粒度是瞬时值。
             * 采样周期与 quality 线程对齐（15s），freshness 给两个周期，
             * 容许一次抖动而不至于让下游立刻判 STALE。
             */
            return {MetricId::CPU_BUSY_RATIO, "cpu_busy_ratio", MetricUnit::PERCENT, MetricScope::HOST,
                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::GAUGE, 15000ms, 30000ms};
        case MetricId::SOFTIRQ_NET_RX_SHARE:
            /*
             * 与 CPU_BUSY_RATIO 同为 HOST 域，但语义完全不同：那个是**时间**
             * 占比，这个是**事件计数**的构成比。同一个 8 核板子上两者会被
             * 一起读，绝不能因为单位同名就混用。
             *
             * GAUGE：源数据是 /dev/weaknet_softirq 的累计次数，本驱动的插件
             * 内部已做区间差值并只发布构成比，对外是瞬时值。
             *
             * 采样周期 15s、freshness 30s，与 CPU_BUSY_RATIO 严格对齐——
             * 两者要在同一轮评估里配对使用，若节奏不同就会出现「用 30 秒前
             * 的软中断构成比去解释 15 秒前的 CPU 忙碌比」这种错配。
             */
            return {MetricId::SOFTIRQ_NET_RX_SHARE, "softirq_net_rx_share", MetricUnit::PERCENT, MetricScope::HOST,
                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::GAUGE, 15000ms, 30000ms};
        default:
            return {id, "unknown", MetricUnit::COUNT, MetricScope::INTERFACE,
                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
    }
}

